import React, { useEffect, useState } from "react";

const Etudiants = () => {
  const [students, setStudents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchStudents = async () => {
      try {
        setLoading(true);
        setError("");
        const token = localStorage.getItem("token");
        
        // Essayer plusieurs routes possibles
        const routesToTry = [
          'http://localhost:5000/api/students',
          'http://localhost:5000/api/etudiants',
          'http://localhost:5000/api/users'
        ];

        let lastError = '';
        
        for (const route of routesToTry) {
          try {
            console.log(`Essai de la route: ${route}`);
            const response = await fetch(route, {
              headers: {
                Authorization: `Bearer ${token}`,
                "Content-Type": "application/json",
              },
            });

            if (response.ok) {
              const result = await response.json();
              console.log(`Réponse de ${route}:`, result);
              
              let studentsData = [];
              
              // Adapter selon la structure de réponse
              if (route.includes('/api/students') && result.students) {
                studentsData = result.students;
              } else if (route.includes('/api/etudiants') && result.etudiants) {
                studentsData = result.etudiants;
              } else if (route.includes('/api/users') && result.users) {
                // Filtrer seulement les étudiants
                studentsData = result.users.filter(user => user.role === 'student');
              } else if (Array.isArray(result)) {
                // Si la réponse est directement un tableau
                studentsData = result.filter(user => user.role === 'student');
              }
              
              if (studentsData.length > 0) {
                setStudents(studentsData);
                return; // Sortir si on a réussi
              }
            } else {
              lastError = `Route ${route}: ${response.status} ${response.statusText}`;
            }
          } catch (routeError) {
            lastError = `Route ${route}: ${routeError.message}`;
            console.log(`Échec de ${route}:`, routeError);
          }
        }
        
        // Si aucune route n'a fonctionné
        setError(`Aucune route valide trouvée. Dernière erreur: ${lastError}`);
        setStudents([]);
        
      } catch (error) {
        console.error("Erreur générale fetch étudiants :", error);
        setError(`Erreur de connexion: ${error.message}`);
        setStudents([]);
      } finally {
        setLoading(false);
      }
    };

    fetchStudents();
  }, []);

  // Le reste du code UI reste identique...
  if (loading) {
    return (
      <div style={{ padding: "2rem", textAlign: "center" }}>
        <div style={{ 
          display: 'flex', 
          flexDirection: 'column', 
          alignItems: 'center',
          justifyContent: 'center',
          minHeight: '200px'
        }}>
          <div style={{
            width: '40px',
            height: '40px',
            border: '4px solid #f3f3f3',
            borderTop: '4px solid #3498db',
            borderRadius: '50%',
            animation: 'spin 1s linear infinite',
            marginBottom: '1rem'
          }}></div>
          <p style={{ fontSize: '1.1rem', color: '#666' }}>Chargement des étudiants...</p>
        </div>
        <style>
          {`
            @keyframes spin {
              0% { transform: rotate(0deg); }
              100% { transform: rotate(360deg); }
            }
          `}
        </style>
      </div>
    );
  }

  if (error) {
    return (
      <div style={{ 
        padding: "2rem", 
        textAlign: "center",
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        minHeight: '200px'
      }}>
        <div style={{
          width: '60px',
          height: '60px',
          backgroundColor: '#fee2e2',
          borderRadius: '50%',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          marginBottom: '1rem'
        }}>
          <span style={{ fontSize: '24px', color: '#dc2626' }}>⚠️</span>
        </div>
        <h3 style={{ color: "#dc2626", marginBottom: '0.5rem' }}>Erreur</h3>
        <p style={{ color: '#666', maxWidth: '400px' }}>{error}</p>
        <div style={{ marginTop: '1rem', display: 'flex', gap: '0.5rem' }}>
          <button 
            onClick={() => window.location.reload()}
            style={{
              padding: '0.5rem 1rem',
              backgroundColor: '#3b82f6',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            Réessayer
          </button>
          <button 
            onClick={() => {
              // Essayer la route /api/etudiants spécifiquement
              const fetchWithRoute = async (route) => {
                setLoading(true);
                setError('');
                try {
                  const token = localStorage.getItem("token");
                  const response = await fetch(route, {
                    headers: { Authorization: `Bearer ${token}` }
                  });
                  if (response.ok) {
                    const result = await response.json();
                    console.log('Réponse manuelle:', result);
                    alert(`Route ${route} fonctionne! Vérifiez la console.`);
                  } else {
                    alert(`Route ${route} échouée: ${response.status}`);
                  }
                } catch (e) {
                  alert(`Erreur ${route}: ${e.message}`);
                } finally {
                  setLoading(false);
                }
              };
              fetchWithRoute('http://localhost:5000/api/etudiants');
            }}
            style={{
              padding: '0.5rem 1rem',
              backgroundColor: '#6b7280',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            Tester /api/etudiants
          </button>
        </div>
      </div>
    );
  }

  // ... (le reste du code d'affichage des étudiants)
};

export default Etudiants;
